import {HM_RULES,HM_MODES,hmRule,hmRuleSummary,validateHMRules} from './hm-rules.js';
import {readAuthoring,completionFlag,findEvent} from './authoring-model.js';
export function hmRulesWorkshop(api){const $=s=>document.querySelector(s),esc=api.esc;let draft;
 function open(){draft=structuredClone(api.project().hmRules||{version:1,moves:{}});list();}
 function list(){api.modal('Global HM rules',`<p>Set the tool and prerequisites for each field move. Empty prerequisite lists allow use immediately. These rules apply to standard HM interactions; explicit free-clears in story scenes remain scripted actions.</p>${Object.entries(HM_RULES).map(([key,h])=>`<button type="button" data-hm-rule="${key}" class="studio-record"><span><b>${h.name}</b><small>${esc(hmRuleSummary({...api.project(),hmRules:draft},key))}${draft.moves[key]?' · Custom':' · Native default'}</small></span><span>Edit</span></button>`).join('')}<p class="hint-line">Tools are reusable and must be in the bag. Owning an HM does not require teaching it. Terrain restrictions and Fly destinations still apply.</p><details><summary>ROM support & limits</summary><p>Export supports English FireRed 1.0 and verified source profiles. Saved scene, flag and quest-stage gates support these three sources. Emerald HM/Dive rules still need their own adapter. Other ROMs can keep drafts. Dive is unavailable in this FireRed engine.</p><p>Original field animations need a non-egg party member. Contextual tools share the party menu’s four field-move slots; pick another member if they are full.</p></details>`,()=>{const p=api.project(),candidate={...p,hmRules:draft};validateHMRules(candidate);api.change(()=>{for(const r of Object.values(draft.moves))for(const c of r.conditions)if(c.kind==='event')completionFlag(p,findEvent(p,c.eventId).n);p.hmRules=structuredClone(draft);});api.toast('Global HM rules saved to the project.');},'Save global rules');document.querySelectorAll('[data-hm-rule]').forEach(b=>b.onclick=()=>edit(b.dataset.hmRule));}
 function edit(effect){const p=api.project(),a=readAuthoring(p),h=HM_RULES[effect],r=structuredClone(hmRule({...p,hmRules:draft},effect)),events=p.maps.flatMap(m=>m.markers.filter(n=>n.runtime?.action==='scene').map(n=>({id:n.id,name:m.name+' / '+n.title}))),flags=(p.questFlags||[]).filter(q=>!q.hidden),variables=a.variables;
  const options=(rows,value)=>rows.map(row=>`<option value="${esc(row.id)}" ${row.id===value?'selected':''}>${esc(row.name)}</option>`).join('');
  function render(){api.modal(h.name+' rules',`<label>Tool requirement<select id="hmRuleMode">${Object.entries(HM_MODES).map(([id,name])=>`<option value="${id}" ${r.mode===id?'selected':''}>${esc(name)}</option>`).join('')}</select></label><div id="hmReplacement" ${r.mode==='item'?'':'hidden'}><label>Replacement item<select id="hmRuleItem"><option value="">Native item number</option>${options(a.items,r.itemRef)}</select></label><label>Native item ID<input id="hmRuleItemID" type="number" min="1" max="65535" value="${r.itemId||13}"></label></div><h3>Prerequisites</h3><p>All listed prerequisites must be met. Remove them all for unrestricted access.</p><div id="hmRuleConditions">${r.conditions.map((c,i)=>`<div class="studio-record" style="display:block"><label>Requirement<select data-hm-kind="${i}">${[['badge','Badge'],['event','Event completed'],['flag','Quest flag'],['variable','Quest stage / counter']].map(([id,name])=>`<option value="${id}" ${c.kind===id||id==='variable'&&c.kind==='option'?'selected':''}>${name}</option>`).join('')}</select></label>${c.kind==='badge'?`<label>Badge number<input data-hm-badge="${i}" type="number" min="1" max="8" value="${c.badge}"></label>`:c.kind==='event'?`<label>Scene<select data-hm-event="${i}"><option value="">Choose a scene</option>${options(events,c.eventId)}</select></label>`:c.kind==='flag'?`<label>Saved flag<select data-hm-flag="${i}"><option value="">Choose a flag</option>${options(flags,c.flagId)}</select></label>`:`<label>Stage counter<select data-hm-variable="${i}"><option value="">Choose a counter</option>${options(variables,c.variableId)}</select></label><label>Comparison<select data-hm-operator="${i}">${[['ge','At least'],['eq','Exactly'],['gt','More than'],['le','At most'],['lt','Less than'],['ne','Anything except']].map(([id,name])=>`<option value="${id}" ${c.operator===id?'selected':''}>${name}</option>`).join('')}</select></label><label>Stage value<input data-hm-value="${i}" type="number" min="0" max="65535" value="${c.value||0}"></label>`}${['event','flag'].includes(c.kind)?`<label>Required state<select data-hm-state="${i}"><option value="yes" ${c.value!==false?'selected':''}>Completed / set</option><option value="no" ${c.value===false?'selected':''}>Not completed / unset</option></select></label>`:''}<button data-hm-remove="${i}" type="button">Remove prerequisite</button></div>`).join('')||'<p>No prerequisites.</p>'}</div><button id="hmRuleAdd" type="button" ${r.conditions.length>=8?'disabled':''}>Add prerequisite</button><div class="studio-actions"><button id="hmRuleNative" type="button">Restore native rules</button><button id="hmRuleCancel" type="button">Back without changes</button></div><p id="hmRuleError" role="alert"></p>`,()=>{read();try{validateHMRules({...p,hmRules:{version:1,moves:{[effect]:r}}});draft.moves[effect]=structuredClone(r);list();}catch(e){$('#hmRuleError').textContent=e.message;}return false;},'Keep rule');
   function read(){r.mode=$('#hmRuleMode').value;r.itemRef=$('#hmRuleItem').value;r.itemId=+$('#hmRuleItemID').value;for(const [i,c]of r.conditions.entries()){const value=name=>$(`[data-hm-${name}="${i}"]`)?.value;if(c.kind==='badge')c.badge=+value('badge');else if(c.kind==='event'){c.eventId=value('event');c.value=value('state')==='yes';}else if(c.kind==='flag'){c.flagId=value('flag');c.value=value('state')==='yes';}else{c.variableId=value('variable');c.operator=value('operator');c.value=+value('value');}}}
   $('#hmRuleMode').onchange=()=>{read();$('#hmReplacement').hidden=r.mode!=='item';};$('#hmRuleAdd').onclick=()=>{read();r.conditions.push({kind:'badge',badge:h.badge});render();};document.querySelectorAll('[data-hm-kind]').forEach(b=>b.onchange=()=>{read();const kind=b.value;r.conditions[+b.dataset.hmKind]=kind==='badge'?{kind,badge:h.badge}:kind==='event'?{kind,eventId:'',value:true}:kind==='flag'?{kind,flagId:'',value:true}:{kind,variableId:'',operator:'ge',value:1};render();});document.querySelectorAll('[data-hm-remove]').forEach(b=>b.onclick=()=>{read();r.conditions.splice(+b.dataset.hmRemove,1);render();});$('#hmRuleNative').onclick=()=>{delete draft.moves[effect];list();};$('#hmRuleCancel').onclick=list;
  }render();
 }
 return{open};}
